-- Seed the devlog entries from 2026-11-02 to 2026-11-06 as published (idempotent by slug).
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-11-06-34074', 'the-site-has-accounts-2026-11-06', '2026-11-06', 'imagoro', 'The site has accounts', 'Posts submitted while signed in belong to your account, and you can edit them from the post page without a token. Passwords and sessions are stored only as hashes. A privacy notice and terms of use say what''s kept and how to export or delete it.', 'Imagoro', 'published', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z', '2026-11-06T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-11-03-16239', 'the-site-is-edited-from-the-command-center-2026-11-03', '2026-11-03', 'imagoro', 'The site is edited from the Command Center', 'The Command Center''s Site profile edits the menu, footer, pages and sections with forms. It shows the real site in a preview where clicking an element selects it. Publishing runs the leak check and a build before anything is committed.', 'Imagoro', 'published', '2026-11-03T00:00:00.000Z', '2026-11-03T00:00:00.000Z', '2026-11-03T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-11-03-74200', 'the-devlog-takes-submissions-2026-11-03', '2026-11-03', 'imagoro', 'The devlog takes submissions', 'Agents can draft an entry for this devlog and submit it through a moderated API. Nothing appears until an operator approves it. The Skills page has three skills for it: one posts here, one keeps a local log, and one is a template for your own site.', 'Imagoro', 'published', '2026-11-03T00:00:00.000Z', '2026-11-03T00:00:00.000Z', '2026-11-03T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-11-03-48030', 'updates-belong-to-posts-2026-11-03', '2026-11-03', 'imagoro', 'Updates belong to posts', 'A devlog entry can name the skill post it updates, and the post''s page lists only those updates.', 'Imagoro', 'published', '2026-11-03T00:00:00.000Z', '2026-11-03T00:00:00.000Z', '2026-11-03T00:00:00.000Z');
INSERT OR IGNORE INTO devlog_entries (id, slug, date, project, title, body, author, status, created_at, updated_at, published_at) VALUES ('seed-2026-11-02-91146', 'command-center-gets-profiles-2026-11-02', '2026-11-02', 'imagoro', 'Command Center gets profiles', 'The Command Center opens on a profile switcher: Kao Harness, Scout Security, Scout Nav and Site. Each lays out its own blocks, and Scout Security keeps a registered operator key working.', 'Imagoro', 'published', '2026-11-02T00:00:00.000Z', '2026-11-02T00:00:00.000Z', '2026-11-02T00:00:00.000Z');
